const p = $('Params').first().json;
const ONLY_OVERRIDE = [];
const r = $input.first().json;
const cur = {};
for (const k of ((r.body && r.body.keys) || [])) { const m = {}; for (const t of (k.translations || [])) { m[t.language_iso] = { v: t.translation || '', by: t.modified_by_email || '' }; } cur[k.key_id] = { a: k.is_archived, m: m }; }
const keys = []; const skipped = [];
for (const it of p.payload) {
  if (ONLY_OVERRIDE.length && ONLY_OVERRIDE.indexOf(it.key_id) < 0) continue;
  const c = cur[it.key_id];
  if (!c) { skipped.push({ key_id: it.key_id, why: 'not found' }); continue; }
  if (c.a) { skipped.push({ key_id: it.key_id, why: 'archived' }); continue; }
  const trs = [];
  for (const iso in it.t) {
    const now = c.m[iso];
    if (now && now.v && now.v.trim()) { if (now.v !== it.t[iso]) skipped.push({ key_id: it.key_id, iso: iso, why: 'target not empty', current: now.v, by: now.by }); continue; }
    trs.push({ language_iso: iso, translation: it.t[iso] });
  }
  if (trs.length) keys.push({ key_id: it.key_id, translations: trs });
}
return [{ json: { body: { keys: keys }, keys_to_write: keys.length, strings_to_write: keys.reduce(function(a,k){return a+k.translations.length;},0), skipped: skipped } }];

const r = $input.first().json; const b = $('Build Body').first().json; const p = $('Params').first().json;
const want = {}; for (const it of p.payload) want[it.key_id] = it.t;
const mism = []; let ok = 0;
for (const k of ((r.body && r.body.keys) || [])) { for (const t of (k.translations || [])) { const w = want[k.key_id] && want[k.key_id][t.language_iso]; if (w === undefined) continue; if (t.translation === w) ok++; else mism.push({ key_id: k.key_id, iso: t.language_iso, got: t.translation, want: w }); } }
return [{ json: { put_status: r.statusCode, errors: (r.body && r.body.errors) || (r.body && r.body.error) || null, written_keys: ((r.body && r.body.keys) || []).length, strings_matching: ok, mismatches: mism.slice(0, 30), sent: b.strings_to_write, skipped: b.skipped } }];
